// Runtime/IO layer: the slice of CPython's `sys` / `os` / `shutil` runtime that this
// program can observe -- argv recovery (UTF-8 + surrogateescape), byte-exact stdout /
// stderr writers, SystemExit, and shutil.get_terminal_size().columns.
//
// node:fs is the only bare specifier in this file: /proc/self/cmdline has to be read to
// recover the raw argv bytes, and fs.writeSync gives us unbuffered, byte-exact output.

import { readFileSync, writeSync } from 'node:fs';
import { decodeSurrogateescape, encodeSurrogateescape } from './surrogateescape.mjs';
import { pyIntFromString } from './int.mjs';

/** Fallback prog name when process.argv[1] is unavailable (mirrors the real script name). */
const FALLBACK_PROG = 'test3.mjs';

/* ------------------------------------------------------------------ argv --- */

let cachedArgv = null;

/**
 * Split /proc/self/cmdline into its entries.
 *
 * The kernel writes each argument NUL-*terminated* (including the last one), so NUL is
 * treated as a terminator rather than a separator. That way a genuinely empty final
 * argument (`prog ''` -> "prog\0\0") survives, while no phantom trailing entry appears.
 */
function splitCmdline(bytes) {
  const parts = [];
  let start = 0;
  for (let i = 0; i < bytes.length; i += 1) {
    if (bytes[i] === 0) {
      parts.push(bytes.subarray(start, i));
      start = i + 1;
    }
  }
  // Defensive: a cmdline that is not NUL-terminated still yields its last entry.
  if (start < bytes.length) parts.push(bytes.subarray(start));
  return parts;
}

/**
 * Recover the raw argv bytes for the user arguments and decode them the way CPython
 * decodes argv on Linux: UTF-8 with errors='surrogateescape', so an undecodable byte B
 * becomes U+DC00+B (spec 3.3). Node's own process.argv has already lost those bytes to
 * U+FFFD, hence the /proc round trip.
 *
 * Alignment: /proc/self/cmdline is [node, ...nodeFlags, script, ...userArgs] while
 * process.argv is [execPath, script, ...userArgs]; taking the LAST
 * (process.argv.length - 2) entries is therefore robust to node flags and to however the
 * interpreter path was spelled.
 */
function recoverArgv() {
  const lossy = process.argv.slice(2);
  const wanted = lossy.length;
  if (wanted === 0) return [];

  const parts = splitCmdline(readFileSync('/proc/self/cmdline'));
  if (parts.length < wanted) return lossy;
  const candidate = parts.slice(parts.length - wanted);

  // Validate the alignment: re-decoding each candidate entry the lossy way Node decoded
  // argv (invalid sequences -> U+FFFD) must reproduce process.argv exactly.
  for (let i = 0; i < wanted; i += 1) {
    if (candidate[i].toString('utf8') !== lossy[i]) return lossy;
  }

  return candidate.map(decodeSurrogateescape);
}

/** sys.argv[1:] -- the user arguments, surrogateescape-decoded. Never throws. */
export function getArgv() {
  if (cachedArgv === null) {
    try {
      cachedArgv = recoverArgv();
    } catch {
      // /proc unreadable (non-Linux, hardened container, ...): Node's lossy argv is the
      // best available approximation.
      cachedArgv = process.argv.slice(2);
    }
  }
  // Hand out a copy: callers treat this like `sys.argv[1:]`, a fresh list every time.
  return cachedArgv.slice();
}

/* ------------------------------------------------------------- prog name --- */

/**
 * os.path.basename(sys.argv[0]) as argparse computes `prog`.
 * Implemented inline (no node:path) so this module's only bare import stays node:fs.
 * Both '/' and '\\' are accepted as separators, and trailing separators are dropped so a
 * path like '/a/b/' still yields a usable name.
 */
export function getProgName() {
  const raw = process.argv[1];
  if (typeof raw !== 'string' || raw === '') return FALLBACK_PROG;

  let end = raw.length;
  while (end > 1 && (raw[end - 1] === '/' || raw[end - 1] === '\\')) end -= 1;
  let start = end;
  while (start > 0 && raw[start - 1] !== '/' && raw[start - 1] !== '\\') start -= 1;

  const base = raw.slice(start, end);
  return base === '' ? FALLBACK_PROG : base;
}

/* ------------------------------------------------------------------- IO --- */

/** Synchronous sleep used only to back off from a full non-blocking pipe. */
function sleepMs(ms) {
  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
}

/**
 * Write every byte of `bytes` to `fd`, synchronously.
 *
 * fs.writeSync is used instead of process.stdout.write because the stream is asynchronous
 * whenever fd 1/2 is a pipe: buffered bytes would then be at the mercy of process.exit().
 * Writing synchronously means output is already on the fd before exit() is reached, which
 * is what makes `node test3.mjs --a 5 --b x | cat` and the two-line error path reliable.
 */
function writeAll(fd, bytes) {
  let offset = 0;
  while (offset < bytes.length) {
    try {
      offset += writeSync(fd, bytes, offset, bytes.length - offset);
    } catch (err) {
      const code = err && err.code;
      if (code === 'EAGAIN') {
        // fd was inherited in non-blocking mode and its pipe buffer is full: wait for the
        // reader to drain, then continue where we left off.
        sleepMs(1);
      } else if (code === 'EINTR') {
        // Interrupted syscall: retry, like CPython's write-with-EINTR-retry loop.
        continue;
      } else if (code === 'EPIPE' || code === 'EBADF') {
        // Reader gone / fd closed. CPython reports BrokenPipeError at shutdown; we
        // deliberately ignore it so a truncated pipe cannot inject extra stderr noise or
        // change the exit status of an otherwise successful run.
        return;
      } else {
        throw err;
      }
    }
  }
}

/** sys.stdout.write(s) -- byte-exact (surrogateescape encoded). */
export function writeStdout(s) {
  if (s === '') return;
  writeAll(1, encodeSurrogateescape(s));
}

/** sys.stderr.write(s) -- byte-exact (surrogateescape encoded). */
export function writeStderr(s) {
  if (s === '') return;
  writeAll(2, encodeSurrogateescape(s));
}

/**
 * SystemExit: terminate with `code`.
 *
 * Nothing needs flushing first -- every byte we emit went out through fs.writeSync above,
 * so there is no pending stream buffer for process.exit() to truncate. process.exitCode is
 * set first so the status is still correct in the (embedder-restricted) case where
 * process.exit() does not terminate the process.
 */
export function exit(code = 0) {
  process.exitCode = code;
  process.exit(code);
}

/* -------------------------------------------------------- terminal size --- */

// Upper bound applied to a COLUMNS value so downstream padding maths stays finite.
// Python happily carries an arbitrarily large int here; any value this big already means
// "never wrap", so clamping is unobservable.
const MAX_COLUMNS = 0x7fffffff;

/**
 * shutil.get_terminal_size().columns, as argparse consumes it:
 *   1. int(os.environ['COLUMNS']) -- full CPython int() semantics (whitespace, sign,
 *      PEP 515 underscores, Unicode Nd digits); KeyError/ValueError -> 0.
 *   2. if that is <= 0, query the terminal attached to *stdout* (argparse asks about
 *      sys.__stdout__ even when it is about to write to stderr).
 *   3. otherwise fall back to 80.
 */
export function getTerminalColumns() {
  let columns = 0;
  const env = process.env.COLUMNS;
  if (typeof env === 'string') {
    try {
      const parsed = pyIntFromString(env);
      columns = parsed > BigInt(MAX_COLUMNS) ? MAX_COLUMNS : Number(parsed);
    } catch {
      columns = 0; // int() raised ValueError
    }
  }

  if (columns <= 0) {
    const tty = process.stdout && process.stdout.columns;
    columns = typeof tty === 'number' && tty > 0 ? tty : 80;
  }

  return columns;
}

// Python builtins that this program uses.

import { pyStr } from './repr.mjs';
import { writeStdout } from './sys.mjs';

/**
 * print(*values) with the default sep=' ' and end='\n': each value goes through str()
 * (pyStr -- notably BigInt renders as a plain decimal expansion) and the result is written
 * to stdout as bytes.
 */
export function print(...values) {
  let out = '';
  for (let i = 0; i < values.length; i += 1) {
    if (i > 0) out += ' '; // sep
  out += pyStr(values[i]);
  }
  writeStdout(out + '\n'); // end
}

