/**
 * CPython's sys.stderr is a TextIOWrapper with errors='backslashreplace', so a code point
 * UTF-8 cannot encode -- i.e. a lone surrogate, such as the U+DCFF that an undecodable
 * argv byte turned into -- reaches the terminal as the literal ASCII text "\udcff".
 * Verified against the reference: `test3_executable --a 5 --b x $'\xff\xfe'` prints
 * `unrecognized arguments: \udcff\udcfe` (backslashes, not raw bytes), while valid
 * non-ASCII text is passed through as plain UTF-8.
 */
function backslashreplaceSurrogates(s) {
  let out = '';
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    // Iterating by code point means a well-formed pair arrives as one cp > 0xFFFF; only
    // genuinely unpaired surrogates land in this range, and they are all 4 hex digits.
    if (cp >= 0xd800 && cp <= 0xdfff) out += `\\u${cp.toString(16).padStart(4, '0')}`;
    else out += ch;
  }
  return out;
}

/** sys.stderr.write(s) -- byte-exact, including stderr's backslashreplace error handler. */
export function writeStderr(s) {
  if (s === '') return;
  const text = /[\ud800-\udfff]/.test(s) ? backslashreplaceSurrogates(s) : s;
  writeAll(2, encodeSurrogateescape(text));
}

